#!/usr/bin/env python3
from __future__ import annotations

import argparse
import json
import os
from pathlib import Path
import sys

SCRIPT_DIR = Path(__file__).resolve().parent

CONFIG_TEMPLATE = """\
# Auto-generated by 01_make_manifest.py

# Input / Output
input_dirs:
{input_dirs}

output_dir: {output_dir}
batch: "batch"
chunks: {chunks}
singularity_image: {singularity_image}

pydock_modules:
  - bindEy

# Files to keep
keep_file_patterns:
  - "*.ene"

# Execution
copy_pdbs_to_tmpdir: true
suppress_stdout: true
suppress_stderr: true

# Chain mapping (optional)
chain_mapping_json: {chain_mapping_json}
chain_mapping_key_mode: "exact"
"""


def q(value) -> str:
    """Quote a value as a YAML double-quoted string."""
    return json.dumps(str(value))


def find_singularity_image(explicit: str | None) -> Path:
    """Use --singularity-image if given, otherwise the .sif located next to this script."""
    if explicit:
        image = Path(os.path.abspath(explicit))
        if not image.is_file():
            raise SystemExit(f"Singularity image not found: {image}")
        return image

    images = sorted(SCRIPT_DIR.glob("*.sif"))
    if not images:
        raise SystemExit(
            f"No .sif Singularity image found in {SCRIPT_DIR}. "
            "Place it next to this script or use --singularity-image."
        )
    if len(images) > 1:
        print(
            f"WARNING: several .sif images in {SCRIPT_DIR}; using {images[-1].name}. "
            "Use --singularity-image to choose another one.",
            file=sys.stderr,
        )
    return Path(os.path.abspath(images[-1]))


def write_config(config_path: Path, input_dirs: list[Path], output_dir: Path, chunks: int,
                 singularity_image: Path, chain_mapping_json: str) -> None:
    text = CONFIG_TEMPLATE.format(
        input_dirs="\n".join(f"  - {q(d)}" for d in input_dirs),
        output_dir=q(output_dir),
        chunks=chunks,
        singularity_image=q(singularity_image),
        chain_mapping_json=q(chain_mapping_json),
    )
    config_path.parent.mkdir(parents=True, exist_ok=True)
    config_path.write_text(text)
    print(f"Wrote config to {config_path}", file=sys.stderr)


def load_config(path: Path) -> dict:
    try:
        import yaml
    except ImportError as exc:
        raise SystemExit("PyYAML is required: conda install pyyaml") from exc
    if not path.is_file():
        raise SystemExit(f"Config file not found: {path} (use --input/--output to create it)")
    with path.open() as fh:
        return yaml.safe_load(fh)


def iter_pdbs(input_dir: Path):
    with os.scandir(input_dir) as it:
        for entry in it:
            if entry.is_file() and entry.name.endswith(".pdb"):
                yield entry.name, Path(entry.path).resolve()


def main() -> int:
    parser = argparse.ArgumentParser(description="Create the pyDock config and the PDB manifest.")
    parser.add_argument("--input", nargs="+", default=None,
                        help="Directory (or directories) with the input PDB files. "
                             "If given, config.yaml is (re)generated.")
    parser.add_argument("--output", default="pydock_output",
                        help="Output directory for pyDock results (default: pydock_output).")
    parser.add_argument("--config", default=str(SCRIPT_DIR / "config.yaml"),
                        help="Config file to write (or read if --input is not given). "
                             "Default: config.yaml next to this script.")
    parser.add_argument("--manifest", default=None,
                        help="Manifest path (default: <output_dir>/manifests/manifest.tsv).")
    parser.add_argument("--chunks", type=int, default=1, help="Number of chunks (default: 1).")
    parser.add_argument("--singularity-image", default=None,
                        help="Path to the pyDock .sif image (default: the .sif next to this script).")
    parser.add_argument("--chain-mapping-json", default="",
                        help="Optional chain mapping JSON (default: none).")
    args = parser.parse_args()

    config_path = Path(args.config).resolve()

    if args.input:
        input_dirs = [Path(d).resolve() for d in args.input]
        for d in input_dirs:
            if not d.is_dir():
                raise SystemExit(f"Input directory does not exist: {d}")
        chain_mapping = str(Path(args.chain_mapping_json).resolve()) if args.chain_mapping_json else ""
        write_config(
            config_path,
            input_dirs=input_dirs,
            output_dir=Path(args.output).resolve(),
            chunks=args.chunks,
            singularity_image=find_singularity_image(args.singularity_image),
            chain_mapping_json=chain_mapping,
        )

    cfg = load_config(config_path)
    output_dir = Path(cfg["output_dir"]).resolve()
    manifest = Path(args.manifest).resolve() if args.manifest else output_dir / "manifests" / "manifest.tsv"
    manifest.parent.mkdir(parents=True, exist_ok=True)

    seen = set()
    count = 0
    with manifest.open("w") as out:
        out.write("batch\tname\tpdb_path\n")
        for raw_input_dir in cfg["input_dirs"]:
            input_dir = Path(raw_input_dir).resolve()
            if not input_dir.is_dir():
                raise SystemExit(f"Input directory does not exist: {input_dir}")
            batch = input_dir.name
            batch_count = 0
            for filename, pdb_path in sorted(iter_pdbs(input_dir)):
                name = pdb_path.stem
                key = (batch, name)
                if key in seen:
                    raise SystemExit(f"Duplicate complex in batch {batch}: {name}")
                seen.add(key)
                out.write(f"{batch}\t{name}\t{pdb_path}\n")
                count += 1
                batch_count += 1
            print(f"{batch}: {batch_count} PDB files", file=sys.stderr)

    if count == 0:
        raise SystemExit("No .pdb files found")
    print(f"Wrote {count} entries to {manifest}", file=sys.stderr)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())